13	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
14	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
15	
16	/**
17	 * 测量提交接口测试：BigDecimal 精确计算、显示值 HALF_UP 4 位、
18	 * 合格判定使用未舍入值且含端点、证书匹配的左闭右开、400/409/422 语义。
19	 */
20	@SpringBootTest
21	@AutoConfigureMockMvc
22	class MeasurementSubmitTest {
23	
24	    @Autowired
25	    private MockMvc mvc;
26	
27	    @Autowired
28	    private JdbcTemplate jdbc;
29	
30	    @BeforeEach
31	    void clean() {
32	        jdbc.update("DELETE FROM release_record");
33	        jdbc.update("DELETE FROM measurement");
34	        jdbc.update("DELETE FROM calibration_certificate");
35	        jdbc.update("DELETE FROM instrument_lock");
36	    }
37	
38	    private void createCert(String instrument, String from, String to, String a, String b) throws Exception {
39	        String json = """
40	                {"instrumentId":"%s","validFrom":"%s","validTo":"%s","a":"%s","b":"%s"}
41	                """.formatted(instrument, from, to, a, b);
42	        mvc.perform(post("/api/certificates").contentType(MediaType.APPLICATION_JSON).content(json))
43	                .andExpect(status().isCreated());
44	    }
45	
46	    private String measurementJson(String key, String instrument, String at, String reading,
47	                                   String lower, String upper, String by) {
48	        return """
49	                {"measurementKey":"%s","instrumentId":"%s","measuredAt":"%s","reading":"%s",
50	                 "lowerLimit":"%s","upperLimit":"%s","submittedBy":"%s"}
51	                """.formatted(key, instrument, at, reading, lower, upper, by);
52	    }
53	
54	    @Test
55	    void submitComputesExactValueAndHalfUpDisplayAndPendingStatus() throws Exception {
56	        // 1.5 × 2.000001 + 0.123456 = 3.1234575（精确）；显示值 HALF_UP 4 位 = 3.1235
57	        createCert("INS-1", "2026-01-01T00:00:00Z", "2027-01-01T00:00:00Z", "1.5", "0.123456");
58	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
59	                        .content(measurementJson("M-1", "INS-1", "2026-06-01T00:00:00Z",
60	                                "2.000001", "0", "3.123458", "alice")))
61	                .andExpect(status().isCreated())
62	                .andExpect(jsonPath("$.computedValue").value("3.1234575"))
63	                .andExpect(jsonPath("$.displayValue").value("3.1235"))
64	                .andExpect(jsonPath("$.passed").value(true))
65	                .andExpect(jsonPath("$.status").value("PENDING"))
66	                .andExpect(jsonPath("$.usable").value(false))
67	                .andExpect(jsonPath("$.certificateId").isNumber())
68	                .andExpect(jsonPath("$.releases").isArray());
69	    }
70	
71	    @Test
72	    void passJudgmentUsesUnroundedValueEvenWhenDisplayLooksInside() throws Exception {
73	        // 未舍入值 1.00004 > 上限 1.00003 → 不合格；但显示值 1.0000 看似落在区间内
74	        createCert("INS-1", "2026-01-01T00:00:00Z", "2027-01-01T00:00:00Z", "1", "0");
75	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
76	                        .content(measurementJson("M-2", "INS-1", "2026-06-01T00:00:00Z",
77	                                "1.00004", "0", "1.00003", "alice")))
78	                .andExpect(status().isCreated())
79	                .andExpect(jsonPath("$.computedValue").value("1.00004"))
80	                .andExpect(jsonPath("$.displayValue").value("1.0000"))
81	                .andExpect(jsonPath("$.passed").value(false));
82	    }
83	
84	    @Test
85	    void passJudgmentIncludesBothEndpoints() throws Exception {
86	        createCert("INS-1", "2026-01-01T00:00:00Z", "2027-01-01T00:00:00Z", "1", "0");
87	        // 计算值恰好等于下限 → 合格
88	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
89	                        .content(measurementJson("M-3", "INS-1", "2026-06-01T00:00:00Z",
90	                                "1.00001", "1.00001", "2", "alice")))
91	                .andExpect(status().isCreated())
92	                .andExpect(jsonPath("$.passed").value(true));
93	        // 计算值恰好等于上限 → 合格
94	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
95	                        .content(measurementJson("M-4", "INS-1", "2026-06-01T00:00:00Z",
96	                                "1.00001", "0", "1.00001", "alice")))
97	                .andExpect(status().isCreated())
98	                .andExpect(jsonPath("$.passed").value(true));
99	    }
100	
101	    @Test
102	    void certificateIntervalIsLeftClosedRightOpen() throws Exception {
103	        createCert("INS-1", "2026-01-01T00:00:00Z", "2027-01-01T00:00:00Z", "1", "0");
104	        // 恰好起点 → 匹配成功
105	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
106	                        .content(measurementJson("M-5", "INS-1", "2026-01-01T00:00:00Z",
107	                                "1", "0", "9", "alice")))
108	                .andExpect(status().isCreated());
109	        // 恰好终点（右开）→ 无匹配 422
110	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
111	                        .content(measurementJson("M-6", "INS-1", "2027-01-01T00:00:00Z",
112	                                "1", "0", "9", "alice")))
113	                .andExpect(status().isUnprocessableEntity())
114	                .andExpect(jsonPath("$.code").value("NO_MATCHING_CERTIFICATE"));
115	        // 区间外 → 422
116	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
117	                        .content(measurementJson("M-7", "INS-9", "2026-06-01T00:00:00Z",
118	                                "1", "0", "9", "alice")))
119	                .andExpect(status().isUnprocessableEntity());
120	    }
121	
122	    @Test
123	    void revokedCertificateCannotMatch() throws Exception {
124	        String body = mvc.perform(post("/api/certificates").contentType(MediaType.APPLICATION_JSON)
125	                        .content("""
126	                                {"instrumentId":"INS-1","validFrom":"2026-01-01T00:00:00Z",
127	                                 "validTo":"2027-01-01T00:00:00Z","a":"1","b":"0"}"""))
128	                .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
129	        long certId = ((Number) com.jayway.jsonpath.JsonPath.read(body, "$.id")).longValue();
130	        mvc.perform(post("/api/certificates/{id}/revoke", certId)).andExpect(status().isOk());
131	
132	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
133	                        .content(measurementJson("M-8", "INS-1", "2026-06-01T00:00:00Z",
134	                                "1", "0", "9", "alice")))
135	                .andExpect(status().isUnprocessableEntity());
136	    }
137	
138	    @Test
139	    void duplicateKeyReturns409AndInvalidInputReturns400() throws Exception {
140	        createCert("INS-1", "2026-01-01T00:00:00Z", "2027-01-01T00:00:00Z", "1", "0");
141	        String json = measurementJson("M-9", "INS-1", "2026-06-01T00:00:00Z", "1", "0", "9", "alice");
142	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON).content(json))
143	                .andExpect(status().isCreated());
144	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON).content(json))
145	                .andExpect(status().isConflict())
146	                .andExpect(jsonPath("$.code").value("DUPLICATE_MEASUREMENT_KEY"));
147	
148	        // 下限大于上限
149	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
150	                        .content(measurementJson("M-10", "INS-1", "2026-06-01T00:00:00Z",
151	                                "1", "9", "0", "alice")))
152	                .andExpect(status().isBadRequest());
153	        // 小数位超过 6 位
154	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
155	                        .content(measurementJson("M-11", "INS-1", "2026-06-01T00:00:00Z",
156	                                "1.0000001", "0", "9", "alice")))
157	                .andExpect(status().isBadRequest());
158	        // 缺少提交人
159	        mvc.perform(post("/api/measurements").contentType(MediaType.APPLICATION_JSON)
160	                        .content("""
161	                                {"measurementKey":"M-12","instrumentId":"INS-1",
162	                                 "measuredAt":"2026-06-01T00:00:00Z","reading":"1",
163	                                 "lowerLimit":"0","upperLimit":"9","submittedBy":""}"""))
164	                .andExpect(status().isBadRequest());
165	    }
166	}
